import type { BankQuestion } from "@/lib/bank";

/** Aldehydes, Ketones and Carboxylic Acids (Chemistry (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-carbonyl-acids-1","question":"Which reagent distinguishes an aldehyde from a ketone?","options":["2,4-Dinitrophenylhydrazine","Tollens' reagent","Sodium bisulphite","Hydroxylamine"],"answer":1,"explanation":"Aldehydes reduce ammoniacal AgNO₃ to a silver mirror; ketones generally do not. 2,4-DNP, NaHSO₃ and NH₂OH react with the C=O group of both.","difficulty":"easy","source":"NEET"},
  {"id":"chem-carbonyl-acids-2","question":"Clemmensen reduction converts a carbonyl group into a CH₂ group using:","options":["Hydrazine and KOH in ethylene glycol","Zinc amalgam and concentrated HCl","H₂ with Pd–BaSO₄","LiAlH₄"],"answer":1,"explanation":"Clemmensen uses Zn–Hg/conc. HCl (acidic). Hydrazine/KOH is the Wolff–Kishner method; LiAlH₄ gives alcohols.","difficulty":"easy","source":"NEET"},
  {"id":"chem-carbonyl-acids-3","question":"Formalin is an aqueous solution of about 40% of:","options":["Methanal","Ethanal","Propanone","Methanol"],"answer":0,"explanation":"Formalin is ~40% HCHO in water, used to preserve biological specimens.","difficulty":"easy","source":"NEET"},
  {"id":"chem-carbonyl-acids-4","question":"Which of the following gives a positive iodoform test?","options":["Ethanal","Propanal","Benzaldehyde","Methanal"],"answer":0,"explanation":"The iodoform test needs a CH₃CO– group (or CH₃CH(OH)–). Ethanal, CH₃CHO, is the only aldehyde that has it.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-5","question":"Which of the following undergoes the Cannizzaro reaction?","options":["Propanal","Propanone","Ethanal","Benzaldehyde"],"answer":3,"explanation":"Cannizzaro needs an aldehyde with no α-hydrogen. Ethanal and propanal have α-H and undergo aldol instead; propanone is a ketone.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-carbonyl-acids-6","question":"Reduction of an acyl chloride to an aldehyde with H₂ over Pd poisoned with BaSO₄ is called the:","options":["Etard reaction","Rosenmund reduction","Stephen reduction","Clemmensen reduction"],"answer":1,"explanation":"Rosenmund: RCOCl + H₂ (Pd–BaSO₄) → RCHO. The poisoned catalyst stops reduction at the aldehyde. Stephen reduction starts from a nitrile.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-7","question":"Which of the following is the strongest acid?","options":["4-Methylbenzoic acid","4-Nitrobenzoic acid","Benzoic acid","4-Methoxybenzoic acid"],"answer":1,"explanation":"The –NO₂ group withdraws electrons (−I, −R) and stabilises the carboxylate. –OCH₃ (+R) and –CH₃ (+I, hyperconjugation) make the acid weaker than benzoic acid.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-8","question":"Ethanal treated with dilute NaOH at room temperature gives:","options":["3-Hydroxybutanal","But-2-enal","Ethanol and sodium ethanoate","Butan-1-ol"],"answer":0,"explanation":"Aldol addition of two CH₃CHO molecules gives CH₃CH(OH)CH₂CHO (aldol). Heating dehydrates it to but-2-enal; ethanol + ethanoate would be a Cannizzaro product, impossible with α-H present.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-9","question":"Carboxylic acids with an α-hydrogen react with Cl₂ or Br₂ in the presence of red phosphorus to give:","options":["Acyl halides","β-Halocarboxylic acids","Alkyl halides with one carbon less","α-Halocarboxylic acids"],"answer":3,"explanation":"This is the Hell–Volhard–Zelinsky reaction: halogenation at the α-carbon.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-carbonyl-acids-10","question":"A ketone also contains a group that is destroyed by strong acid. Which method best reduces its C=O group to CH₂?","options":["Wolff–Kishner reduction","Clemmensen reduction","Reduction with NaBH₄","Rosenmund reduction"],"answer":0,"explanation":"Wolff–Kishner (NH₂NH₂, then KOH in ethylene glycol, heat) works in strongly basic conditions, so acid-sensitive groups survive. NaBH₄ stops at the alcohol.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-11","question":"The correct order of reactivity towards nucleophilic addition is:","options":["CH₃CHO > HCHO > C₆H₅COC₆H₅ > CH₃COCH₃","C₆H₅COC₆H₅ > CH₃COCH₃ > CH₃CHO > HCHO","CH₃COCH₃ > CH₃CHO > HCHO > C₆H₅COC₆H₅","HCHO > CH₃CHO > CH₃COCH₃ > C₆H₅COC₆H₅"],"answer":3,"explanation":"Alkyl and aryl groups reduce the positive charge on the carbonyl carbon and add steric hindrance; benzophenone, with two phenyls in resonance, is least reactive.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-12","question":"Toluene treated with chromyl chloride in CS₂, followed by hydrolysis, gives:","options":["Benzoic acid","Benzophenone","Benzyl alcohol","Benzaldehyde"],"answer":3,"explanation":"This is the Etard reaction: CrO₂Cl₂ forms a chromium complex that hydrolyses to benzaldehyde, stopping before benzoic acid.","difficulty":"hard","source":"NEET"},
  {"id":"chem-carbonyl-acids-13","question":"A mixture of formaldehyde and benzaldehyde is heated with concentrated NaOH. The products are mainly:","options":["Sodium benzoate and benzyl alcohol only","Methanol and sodium formate only","Sodium benzoate and methanol","Sodium formate and benzyl alcohol"],"answer":3,"explanation":"In the crossed Cannizzaro reaction HCHO, the more reactive aldehyde, is attacked by OH⁻ and acts as the hydride donor, so it is oxidised to formate while benzaldehyde is reduced.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-14","question":"A mixture of ethanal and propanal is treated with dilute NaOH. The number of different aldol (β-hydroxy aldehyde) products possible is:","options":["6","3","4","2"],"answer":2,"explanation":"Two self-aldols (ethanal + ethanal, propanal + propanal) and two crossed aldols (each aldehyde acting as the enolate towards the other): 4 products.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-carbonyl-acids-15","question":"Sodium propanoate heated with soda lime gives:","options":["Propane","Butane","Ethane","Methane"],"answer":2,"explanation":"Decarboxylation: CH₃CH₂COONa + NaOH (CaO) → CH₃CH₃ + Na₂CO₃. The alkane has one carbon fewer.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-16","question":"Ethanenitrile is reduced by SnCl₂/HCl and the product is hydrolysed to give ethanal. The reaction is called the:","options":["Rosenmund reduction","Gattermann–Koch reaction","Stephen reaction","Hoffmann bromamide reaction"],"answer":2,"explanation":"Stephen reaction: RC≡N + SnCl₂/HCl → imine hydrochloride, then H₃O⁺ → RCHO.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-17","question":"The correct order of acid strength is:","options":["C₆H₅COOH > HCOOH > CH₃COOH","HCOOH > C₆H₅COOH > CH₃COOH","CH₃COOH > C₆H₅COOH > HCOOH","C₆H₅COOH > CH₃COOH > HCOOH"],"answer":1,"explanation":"pKa: HCOOH 3.75, C₆H₅COOH 4.19, CH₃COOH 4.76. The +I methyl weakens acetic acid; formic acid has no electron-donating group.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-carbonyl-acids-18","question":"When semicarbazide, H₂N–NH–CO–NH₂, reacts with a carbonyl compound, the nitrogen that attacks the carbonyl carbon is:","options":["The NH between the two other groups","The NH₂ attached directly to C=O","The terminal NH₂ of the –NH–NH₂ end, because the other two nitrogens are in resonance with the C=O group","Any of the three equally"],"answer":2,"explanation":"The –NH– and the amide –NH₂ have their lone pairs delocalised into the C=O, making them poor nucleophiles. Only the free hydrazine-type NH₂ attacks.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-19","question":"How many of the following statements are correct? (A) Benzaldehyde gives a red precipitate with Fehling's solution. (B) Formic acid gives a silver mirror with Tollens' reagent. (C) Acetophenone gives a positive iodoform test. (D) Propanone forms a crystalline addition product with sodium hydrogensulphite.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"B (HCOOH has an –CHO-like H), C (CH₃CO– group) and D are correct. A is wrong: aromatic aldehydes do not respond to Fehling's test.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-20","question":"Assertion (A): Carboxylic acids do not give the typical reactions of the carbonyl group, such as forming oximes or phenylhydrazones. Reason (R): Resonance in the –COOH group lowers the electrophilic character of its carbonyl carbon.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true: the lone pair on the –OH oxygen is delocalised onto C=O, so the carbon is much less positive and nucleophilic addition does not occur.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-carbonyl-acids-21","question":"Match the name reaction (Column I) with its description (Column II). (a) Gattermann–Koch, (b) Cannizzaro, (c) Kolbe electrolysis, (d) Hell–Volhard–Zelinsky. (1) α-Halogenation of a carboxylic acid; (2) Electrolysis of a carboxylate salt to give an alkane; (3) Benzene + CO + HCl (anhydrous AlCl₃/CuCl) → benzaldehyde; (4) Disproportionation of an aldehyde without α-H.","options":["a-3, b-2, c-4, d-1","a-4, b-3, c-2, d-1","a-3, b-4, c-1, d-2","a-3, b-4, c-2, d-1"],"answer":3,"explanation":"Gattermann–Koch formylates benzene; Cannizzaro is disproportionation; Kolbe electrolysis couples R groups (2RCOO⁻ → R–R + 2CO₂); HVZ halogenates the α-carbon.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-22","question":"Ethanoic acid is treated with (i) SOCl₂, (ii) H₂, Pd–BaSO₄ and (iii) dilute NaOH followed by heating. The final product is:","options":["But-2-enal","Ethanol","3-Hydroxybutanal","Butanal"],"answer":0,"explanation":"SOCl₂ → CH₃COCl; Rosenmund → CH₃CHO; dilute NaOH gives aldol, which on heating loses water to give CH₃CH=CHCHO (but-2-enal).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-23","question":"A compound C₄H₈O forms an orange precipitate with 2,4-DNP and gives a positive iodoform test, but does not reduce Tollens' reagent. The compound is:","options":["2-Methylpropanal","Butan-2-one","Butanal","But-3-en-2-ol"],"answer":1,"explanation":"DNP-positive means C=O; Tollens-negative rules out the aldehydes; iodoform-positive needs CH₃CO–. But-3-en-2-ol gives iodoform but has no C=O, so it is DNP-negative.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-24","question":"Which is the correct order of acid strength?","options":["CCl₃COOH > CF₃COOH > CHCl₂COOH > CH₂ClCOOH","CF₃COOH > CHCl₂COOH > CCl₃COOH > CH₂ClCOOH","CH₂ClCOOH > CHCl₂COOH > CCl₃COOH > CF₃COOH","CF₃COOH > CCl₃COOH > CHCl₂COOH > CH₂ClCOOH"],"answer":3,"explanation":"More and more electronegative halogens give a stronger −I effect. Three F atoms (pKa ≈ 0.2) outdo three Cl (≈ 0.7), which beat two Cl (≈ 1.3) and one Cl (≈ 2.9).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-25","question":"Which carbonyl compound, treated with C₂H₅MgBr followed by aqueous work-up, gives butan-2-ol?","options":["Propanal","Ethanal","Methanal","Propanone"],"answer":1,"explanation":"CH₃CHO + C₂H₅⁻ → CH₃CH(OH)C₂H₅ (butan-2-ol). Methanal gives propan-1-ol, propanone gives 2-methylbutan-2-ol, and propanal gives pentan-3-ol.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-26","question":"Which of the following does NOT give a positive iodoform test?","options":["Ethanol","Propan-2-ol","Acetophenone","Pentan-3-one"],"answer":3,"explanation":"Pentan-3-one (C₂H₅COC₂H₅) has no CH₃CO– group. Ethanol and propan-2-ol are oxidised by the hypoiodite to CH₃CHO and CH₃COCH₃, which then react.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-carbonyl-acids-27","question":"0.37 g of a saturated monocarboxylic acid needs 25 mL of 0.2 M NaOH for neutralisation. The acid is:","options":["Butanoic acid","Propanoic acid","Ethanoic acid","Methanoic acid"],"answer":1,"explanation":"n(NaOH) = 0.025 × 0.2 = 5 × 10⁻³ mol = n(acid). M = 0.37/0.005 = 74 g/mol, which is C₂H₅COOH.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-28","question":"How many of the following statements are correct? (A) Benzaldehyde with concentrated NaOH gives benzyl alcohol and sodium benzoate. (B) Benzoic acid readily undergoes Friedel–Crafts alkylation. (C) Ketones are more reactive than aldehydes towards nucleophilic addition because the two alkyl groups stabilise the transition state. (D) Ethanal reacts with HCN to give a racemic mixture of the cyanohydrin.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A (Cannizzaro) and D (CN⁻ attacks the planar C=O equally from both faces) are correct. B is wrong: –COOH deactivates the ring and binds AlCl₃. C is wrong: ketones are less reactive for steric and electronic reasons.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-29","question":"Ethanoic acid is esterified with methanol labelled with ¹⁸O (CH₃¹⁸OH) in the presence of acid. The ¹⁸O label is found:","options":["Shared equally between ester and water","In the water formed","In the ester, as the alkoxy oxygen","In the carbonyl oxygen of the ester"],"answer":2,"explanation":"In acid-catalysed esterification the alcohol oxygen attacks the protonated carbonyl and the acid loses its –OH as water, so the label stays in CH₃CO–¹⁸O–CH₃.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-30","question":"Benzaldehyde reacts with propanone in the presence of dilute NaOH. The main product is:","options":["C₆H₅COCH₃","C₆H₅CH=CHCOCH₃ (benzalacetone)","C₆H₅CH(OH)CH₃","C₆H₅CH₂OH and CH₃COONa"],"answer":1,"explanation":"This is a Claisen–Schmidt (crossed aldol) condensation: the enolate of propanone attacks benzaldehyde (no α-H) and the aldol dehydrates to the conjugated enone.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-31", "question": "The IUPAC name of (CH₃)₂CH–CH₂–CHO is:", "options": ["3-Methylbutanal", "3-Methylbutan-2-one", "2-Methylbutanal", "Pentanal"], "answer": 0, "explanation": "Number the chain from the CHO carbon (C-1): CHO–CH₂–CH(CH₃)–CH₃ is a four-carbon chain with a methyl on C-3, so it is 3-methylbutanal (isovaleraldehyde).", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-32", "question": "The acid present in the sting of red ants and nettles is:", "options": ["Methanoic acid", "Citric acid", "Ethanoic acid", "Oxalic acid"], "answer": 0, "explanation": "Methanoic acid (formic acid, from Latin formica, ant) is present in ant and nettle stings.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-33", "question": "Which reagent oxidises a primary alcohol to an aldehyde without further oxidation to the carboxylic acid?", "options": ["Acidified KMnO₄", "Concentrated HNO₃", "Hot acidified K₂Cr₂O₇ in excess", "PCC (pyridinium chlorochromate)"], "answer": 3, "explanation": "PCC (a complex of CrO₃, pyridine and HCl) in CH₂Cl₂ stops at the aldehyde. Strong oxidants such as KMnO₄ or excess dichromate carry the oxidation on to the carboxylic acid.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-34", "question": "Ethylbenzene is heated with alkaline KMnO₄ and the mixture is then acidified. The product is:", "options": ["Benzoic acid", "Benzaldehyde", "Phenylethanoic acid", "Acetophenone"], "answer": 0, "explanation": "Vigorous oxidation converts the whole side chain (with a benzylic H) into –COOH, whatever its length, so ethylbenzene gives benzoic acid (the extra carbon leaves as CO₂).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-35", "question": "Ethanal reacts with HCN, and the product is hydrolysed with dilute acid. The final product is:", "options": ["2-Hydroxypropanenitrile", "Propanal", "Propanoic acid", "2-Hydroxypropanoic acid (lactic acid)"], "answer": 3, "explanation": "CH₃CHO + HCN → CH₃CH(OH)CN (a cyanohydrin); hydrolysis turns –CN into –COOH, giving CH₃CH(OH)COOH, lactic acid. The cyanohydrin is only the intermediate.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-36", "question": "Ketones react with ethylene glycol in the presence of dry HCl to give:", "options": ["Cyclic ketals, used to protect the carbonyl group", "Hemiacetals that cannot be isolated", "Aldol products", "Esters"], "answer": 0, "explanation": "With ethane-1,2-diol and dry HCl, ketones form five-membered cyclic ketals (ethylene ketals). They are stable to bases and are hydrolysed back to the ketone by aqueous acid, so they protect the C=O group.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-37", "question": "Which is the correct order of boiling points of these compounds of comparable molar mass?", "options": ["n-Butane < propanal < methoxyethane < propan-1-ol", "Methoxyethane < n-butane < propan-1-ol < propanal", "Propanal < n-butane < methoxyethane < propan-1-ol", "n-Butane < methoxyethane < propanal < propan-1-ol"], "answer": 3, "explanation": "Propanal (polar C=O, dipole–dipole forces) boils above the weakly polar ether and non-polar butane, but below propan-1-ol, which is hydrogen-bonded (bp: 273, 281, 322 and 370 K).", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "chem-carbonyl-acids-38", "question": "Carboxylic acids boil at higher temperatures than alcohols of comparable molar mass mainly because:", "options": ["They are ionised in the liquid state", "They form strongly hydrogen-bonded dimers that persist even in the vapour", "They have higher molar masses", "They have weaker van der Waals forces"], "answer": 1, "explanation": "Two –COOH groups form a pair of hydrogen bonds (a cyclic dimer); this association is more extensive than in alcohols and persists even in the vapour phase.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-39", "question": "The correct order of reactivity of acid derivatives towards nucleophilic acyl substitution is:", "options": ["Amide > ester > anhydride > acyl chloride", "Ester > acyl chloride > amide > anhydride", "Acyl chloride > anhydride > ester > amide", "Anhydride > acyl chloride > amide > ester"], "answer": 2, "explanation": "Reactivity follows how good the leaving group is (Cl⁻ > RCOO⁻ > RO⁻ > NH₂⁻) and how weakly it donates electrons to C=O by resonance. Amides are least reactive because the N lone pair delocalises strongly.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-40", "question": "Which reagent reduces the aldehyde group of a compound to CH₂OH but leaves a –COOH group in the same molecule unchanged?", "options": ["H₂ with Ni at high temperature and pressure", "LiAlH₄", "NaBH₄", "Diborane (B₂H₆) in excess"], "answer": 2, "explanation": "NaBH₄ is a mild hydride donor: it reduces aldehydes and ketones but not carboxylic acids or esters. LiAlH₄ and diborane both reduce –COOH to –CH₂OH.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-41", "question": "Acetophenone is warmed with aqueous sodium hypochlorite and the mixture is acidified. The organic products are:", "options": ["Benzaldehyde and chloroform", "Benzoic acid and chloroform", "Phenylethanoic acid and CHCl₃", "Chloroacetophenone only"], "answer": 1, "explanation": "C₆H₅COCH₃ is a methyl ketone; NaOCl halogenates the methyl group to –CCl₃, which is cleaved by base (haloform reaction) to give sodium benzoate and CHCl₃. Acidification gives benzoic acid.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-42", "question": "Benzaldehyde is treated with a mixture of conc. HNO₃ and conc. H₂SO₄ at 273–283 K. The main product is:", "options": ["Nitrobenzene", "2-Nitrobenzaldehyde", "3-Nitrobenzaldehyde", "4-Nitrobenzaldehyde"], "answer": 2, "explanation": "–CHO withdraws electrons by −I and −R effects; it deactivates the ring and directs electrophiles to the meta position.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-43", "question": "To prepare 2-methylpropanoic acid by carboxylating a Grignard reagent with dry ice, the alkyl bromide needed is:", "options": ["2-Bromopropane", "Bromoethane", "1-Bromopropane", "2-Bromobutane"], "answer": 0, "explanation": "RMgX + CO₂ → RCOOMgX → RCOOH adds one carbon. (CH₃)₂CHMgBr (from 2-bromopropane) gives (CH₃)₂CH–COOH. 1-Bromopropane would give butanoic acid.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-44", "question": "Benzonitrile is treated with CH₃MgBr and the product is hydrolysed with dilute acid. The final product is:", "options": ["Benzaldehyde", "Acetophenone", "Benzoic acid", "1-Phenylethanol"], "answer": 1, "explanation": "The Grignard reagent adds to C≡N to give an imine salt, C₆H₅C(=NMgBr)CH₃, which is hydrolysed to the ketone C₆H₅COCH₃.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-45", "question": "Ethanoyl chloride reacts with dimethylcadmium. The product is:", "options": ["tert-Butyl alcohol", "Ethanal", "Methyl ethanoate", "Propanone"], "answer": 3, "explanation": "2CH₃COCl + (CH₃)₂Cd → 2CH₃COCH₃ + CdCl₂. Dialkylcadmiums are less reactive than Grignard reagents, so the reaction stops at the ketone and does not go on to the tertiary alcohol.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-46", "question": "Which of the following oximes can exist as a pair of geometrical (E/Z) isomers?", "options": ["Formaldehyde oxime", "Benzophenone oxime", "Acetone oxime", "Acetaldehyde oxime"], "answer": 3, "explanation": "E/Z isomerism about C=N needs two different groups on the carbon. CH₃CH=NOH has CH₃ and H; acetone (two CH₃), formaldehyde (two H) and benzophenone (two C₆H₅) oximes do not.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-47", "question": "Propanal is warmed with dilute NaOH, and the aldol product is heated to dehydrate it. The final product is:", "options": ["3-Hydroxy-2-methylpentanal", "Pent-2-enal", "2-Methylpent-2-enal", "Hex-2-enal"], "answer": 2, "explanation": "The enolate of propanal (from C-2) adds to another propanal: CH₃CH₂CH(OH)CH(CH₃)CHO (3-hydroxy-2-methylpentanal). Loss of water gives CH₃CH₂CH=C(CH₃)CHO, 2-methylpent-2-enal.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-48", "question": "Ethyl benzoate can be converted directly into benzaldehyde with:", "options": ["Zn–Hg and conc. HCl", "DIBAL-H at low temperature, then hydrolysis", "LiAlH₄ in excess", "NaBH₄ in ethanol"], "answer": 1, "explanation": "Diisobutylaluminium hydride reduces esters (and nitriles) only as far as aldehydes at low temperature. LiAlH₄ reduces esters to alcohols, NaBH₄ does not reduce esters, and Clemmensen reagent reduces ketones to CH₂.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-49", "question": "How many of the following statements are correct? (A) Ketones are generally less reactive than aldehydes towards nucleophilic addition for both steric and electronic reasons. (B) Benzaldehyde is less reactive than propanal towards nucleophilic addition. (C) Sodium hydrogensulphite adds readily to all ketones. (D) Hydrogensulphite addition products give back the carbonyl compound with dilute acid or alkali.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B (resonance of the ring with C=O lowers the electrophilicity) and D are correct; D is used to purify aldehydes. C is wrong: bulky ketones add NaHSO₃ poorly; mainly aldehydes and methyl ketones react.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-carbonyl-acids-50", "question": "Assertion (A): The α-hydrogens of aldehydes and ketones are acidic. Reason (R): The carbanion (enolate) formed on removing an α-hydrogen is stabilised by resonance with the carbonyl group.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the negative charge of the enolate is delocalised onto the electronegative oxygen, and the −I effect of C=O also helps. This acidity underlies aldol and haloform reactions.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-51", "question": "Match the reagent (Column I) with the product it gives from benzaldehyde (Column II). (a) NaBH₄, (b) HCN, (c) NH₂OH, (d) conc. NaOH. (1) Benzaldoxime, (2) Benzyl alcohol, (3) Mandelonitrile (a cyanohydrin), (4) Benzyl alcohol and sodium benzoate.", "options": ["a-2, b-3, c-4, d-1", "a-4, b-3, c-1, d-2", "a-2, b-1, c-3, d-4", "a-2, b-3, c-1, d-4"], "answer": 3, "explanation": "NaBH₄ reduces CHO to CH₂OH (2); HCN adds to give C₆H₅CH(OH)CN (3); NH₂OH gives the oxime C₆H₅CH=NOH (1); concentrated NaOH causes the Cannizzaro reaction (4).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-52", "question": "Ethanoic acid is treated in turn with (i) Cl₂ and red phosphorus, (ii) KCN, and (iii) H₃O⁺ with warming. The product of step (iii) is:", "options": ["Succinic acid", "Propanedioic acid (malonic acid)", "2-Hydroxypropanoic acid", "Propanoic acid"], "answer": 1, "explanation": "HVZ gives ClCH₂COOH; CN⁻ displaces Cl to give NC–CH₂–COOH; hydrolysis of –CN gives HOOC–CH₂–COOH, malonic acid (which loses CO₂ only on stronger heating).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-53", "question": "Considering structural isomers only, how many aldehydes and ketones have the formula C₅H₁₀O, and how many of them give a positive iodoform test?", "options": ["6 isomers; 2 give iodoform", "7 isomers; 3 give iodoform", "8 isomers; 3 give iodoform", "7 isomers; 2 give iodoform"], "answer": 3, "explanation": "Aldehydes: pentanal, 2-methylbutanal, 3-methylbutanal, 2,2-dimethylpropanal (4). Ketones: pentan-2-one, pentan-3-one, 3-methylbutan-2-one (3). Total 7; only the two methyl ketones (pentan-2-one and 3-methylbutan-2-one) have CH₃CO– and give iodoform.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-carbonyl-acids-54", "question": "A mixture of 2.2 g of ethanal and 2.9 g of propanone is warmed with excess Tollens' reagent. The mass of silver deposited is (Ag = 108):", "options": ["5.4 g", "10.8 g", "21.6 g", "16.2 g"], "answer": 1, "explanation": "Only the aldehyde reduces Tollens' reagent: RCHO + 2[Ag(NH₃)₂]⁺ → RCOO⁻ + 2Ag. Ethanal = 2.2/44 = 0.05 mol, giving 0.10 mol Ag = 10.8 g. 21.6 g wrongly counts propanone too.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-carbonyl-acids-55", "question": "0.501 g of the silver salt of a monobasic carboxylic acid leaves 0.324 g of silver on ignition (Ag = 108). The acid is:", "options": ["Methanoic acid", "Propanoic acid", "Ethanoic acid", "Benzoic acid"], "answer": 2, "explanation": "Moles of salt = moles of Ag = 0.324/108 = 0.003. Molar mass of RCOOAg = 0.501/0.003 = 167, so the acid RCOOH = 167 − 108 + 1 = 60, i.e. CH₃COOH.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-carbonyl-acids-56", "question": "Glyoxal (OHC–CHO) is heated with concentrated NaOH. The product is:", "options": ["Sodium formate", "Sodium oxalate", "Sodium glycolate (HOCH₂COONa)", "Ethane-1,2-diol and sodium oxalate"], "answer": 2, "explanation": "This is an intramolecular Cannizzaro reaction: one CHO group is oxidised to COO⁻ and the other reduced to CH₂OH in the same molecule, giving HOCH₂–COO⁻Na⁺.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-carbonyl-acids-57", "question": "Hexane-2,5-dione is warmed with aqueous base. The main product of intramolecular aldol condensation is:", "options": ["2-Methylcyclopent-2-en-1-one", "3-Methylcyclopent-2-en-1-one", "Cyclohex-2-en-1-one", "2,5-Dimethylfuran"], "answer": 1, "explanation": "The enolate of a terminal CH₃ (C-1) attacks the C-5 carbonyl, forming a five-membered ring (C-1 to C-5). Dehydration gives a conjugated enone in which the methyl sits on the β-carbon: 3-methylcyclopent-2-en-1-one.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-carbonyl-acids-58", "question": "How many of the following statements are correct? (A) Carboxylic acids liberate CO₂ from aqueous NaHCO₃, which distinguishes them from phenols. (B) Diborane does not reduce the –COOH group. (C) LiAlH₄ reduces carboxylic acids to primary alcohols. (D) Carboxylic acids react with ammonia at room temperature to give amides directly.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and C are correct. B is wrong: diborane reduces –COOH readily (it does not easily reduce esters or nitro groups). D is wrong: at room temperature an ammonium salt forms; the amide is obtained only on strong heating.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-59", "question": "An aqueous mixture of sodium ethanoate and sodium propanoate is electrolysed (Kolbe electrolysis). How many different alkanes can form at the anode?", "options": ["One", "Four", "Three", "Two"], "answer": 2, "explanation": "The anode gives CH₃• and C₂H₅• radicals, which combine in three ways: CH₃–CH₃ (ethane), CH₃–C₂H₅ (propane) and C₂H₅–C₂H₅ (butane).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-carbonyl-acids-60", "question": "Benzene is treated in turn with (i) CH₃COCl/anhydrous AlCl₃, (ii) I₂ and NaOH, then acidification, and (iii) soda lime with heating of the sodium salt. The final organic product is:", "options": ["Benzoic acid", "Toluene", "Acetophenone", "Benzene"], "answer": 3, "explanation": "(i) gives acetophenone; (ii) the iodoform reaction turns C₆H₅COCH₃ into benzoic acid (plus CHI₃); (iii) decarboxylation of sodium benzoate with soda lime removes CO₂, giving benzene again.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-carbonyl-acids-61", "question": "Benzoyl chloride is treated with excess LiAlH₄ in dry ether, followed by aqueous work-up. The product is:", "options": ["Benzyl alcohol", "Benzaldehyde", "Toluene", "Benzoic acid"], "answer": 0, "explanation": "LiAlH₄ first reduces C₆H₅COCl to benzaldehyde, which is more reactive than the acyl chloride and is reduced at once to C₆H₅CH₂OH. Stopping at the aldehyde needs a deactivated reagent such as H₂/Pd–BaSO₄ (Rosenmund) or LiAlH(OtBu)₃.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-62", "question": "Propanone is warmed with aqueous sodium hypobromite (Br₂ + NaOH). The products are:", "options": ["Bromoacetone and NaBr", "Bromoform and sodium ethanoate", "Bromoform and sodium formate", "1,3-Dibromopropanone and water"], "answer": 1, "explanation": "In base the CH₃ group next to C=O is brominated three times (each Br makes the next α-H more acidic), and OH⁻ then cleaves off CBr₃⁻, which picks up H⁺: CH₃COCH₃ + 3NaOBr → CHBr₃ + CH₃COONa + 2NaOH. The remaining two carbons stay as acetate, not formate.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-63", "question": "Acetoacetic acid, CH₃COCH₂COOH, loses CO₂ easily on gentle warming. The organic product is:", "options": ["Ethanoic acid", "Propanal", "Propanone", "Propanoic acid"], "answer": 2, "explanation": "β-Keto acids decarboxylate through a six-membered cyclic transition state in which the carboxyl H moves to the keto oxygen, giving the enol of propanone, which tautomerises to CH₃COCH₃. Simple carboxylic acids need soda lime and strong heating instead.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-64", "question": "Propanone is kept in contact with Ba(OH)₂, and the product is then heated with a trace of acid (or I₂). The final product is:", "options": ["4-Hydroxy-4-methylpentan-2-one", "2-Methylpent-2-enal", "Phorone, (CH₃)₂C=CH–CO–CH=C(CH₃)₂", "4-Methylpent-3-en-2-one (mesityl oxide)"], "answer": 3, "explanation": "Base-catalysed aldol addition of two propanone molecules gives diacetone alcohol, (CH₃)₂C(OH)CH₂COCH₃; heating with acid dehydrates it to the α,β-unsaturated ketone (CH₃)₂C=CH–COCH₃. Phorone needs a third propanone molecule and is a minor product.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-65", "question": "Arrange butanoic acid and its 2-, 3- and 4-chloro derivatives in decreasing order of acidic strength:", "options": ["2-Chlorobutanoic > 3-chlorobutanoic > 4-chlorobutanoic > butanoic acid", "4-Chlorobutanoic > 3-chlorobutanoic > 2-chlorobutanoic > butanoic acid", "Butanoic > 4-chlorobutanoic > 3-chlorobutanoic > 2-chlorobutanoic acid", "2-Chlorobutanoic > 4-chlorobutanoic > 3-chlorobutanoic > butanoic acid"], "answer": 0, "explanation": "pKa ≈ 2.9, 4.1, 4.5 and 4.8 respectively. The −I effect of Cl stabilises the carboxylate but dies away rapidly through each additional C–C bond, so the nearer the Cl to –COOH, the stronger the acid.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-66", "question": "The correct order of the rate of acid-catalysed esterification with methanol is:", "options": ["(CH₃)₃CCOOH > (CH₃)₂CHCOOH > CH₃COOH > HCOOH", "HCOOH > CH₃COOH > (CH₃)₂CHCOOH > (CH₃)₃CCOOH", "CH₃COOH > HCOOH > (CH₃)₃CCOOH > (CH₃)₂CHCOOH", "All react at the same rate, as all are monocarboxylic acids"], "answer": 1, "explanation": "The slow step is attack of methanol on the protonated carbonyl carbon to give a crowded tetrahedral intermediate; increasing branching at the α-carbon hinders this attack, so the rate falls as H < CH₃ < (CH₃)₂CH < (CH₃)₃C grows in size.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-67", "question": "Benzaldehyde is treated with HCN (with a trace of base). The cyanohydrin obtained is:", "options": ["Optically active, mainly the R enantiomer", "Optically active, mainly the S enantiomer", "A racemic mixture, hence optically inactive", "A meso compound"], "answer": 2, "explanation": "CN⁻ attacks the planar trigonal carbonyl carbon equally from either face, giving equal amounts of (R)- and (S)-mandelonitrile. A new stereocentre created from achiral reactants without a chiral catalyst always gives a racemate; a meso form needs two stereocentres.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-68", "question": "Formic acid and oxalic acid are each heated with concentrated H₂SO₄. The gases evolved are respectively:", "options": ["CO₂; CO", "CO and H₂; CO₂ only", "CO₂ and H₂; CO and H₂O", "CO; CO and CO₂"], "answer": 3, "explanation": "Conc. H₂SO₄ dehydrates both acids: HCOOH → CO + H₂O, and (COOH)₂ → CO + CO₂ + H₂O. Formic acid gives no CO₂ under these conditions, which is a common slip.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-69", "question": "Phthalic anhydride is heated with aqueous ammonia (and the product heated strongly). The final product is:", "options": ["Phthalimide", "Phthalic acid", "Anthranilic acid", "Benzamide"], "answer": 0, "explanation": "NH₃ opens the anhydride to the ammonium salt of phthalamic acid, which on strong heating loses water and closes to the cyclic imide, phthalimide — the starting material of Gabriel synthesis. Anthranilic acid needs a further Hofmann reaction with Br₂/NaOH.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-70", "question": "A compound contains both a –COOH group and a –COOC₂H₅ group. Which reagent reduces the –COOH group to –CH₂OH while leaving the ester largely untouched?", "options": ["LiAlH₄", "B₂H₆ (diborane) in THF", "NaBH₄ in ethanol", "H₂/Pd–BaSO₄"], "answer": 1, "explanation": "Diborane is electrophilic and reacts quickly with the acidic –COOH (forming an acyloxyborane that is reduced to RCH₂OH), but reacts only slowly with esters. LiAlH₄ reduces both groups; NaBH₄ reduces neither under normal conditions; the Rosenmund catalyst reduces acyl chlorides.", "difficulty": "hard", "source": "JEE Main"},
  {"id":"chem-carbonyl-acids-71","question":"Ethanal is heated with excess methanal and concentrated NaOH. The product is pentaerythritol, C(CH₂OH)₄, along with sodium formate. How many molecules of methanal are consumed per molecule of ethanal, and by which reactions?","options":["3 molecules; three aldol additions only","2 molecules; two aldol additions and one Cannizzaro reaction","4 molecules; three crossed aldol additions and one crossed Cannizzaro reaction","4 molecules; four aldol additions"],"answer":2,"explanation":"The three α-hydrogens of ethanal each undergo crossed aldol with HCHO, giving (HOCH₂)₃C–CHO, which has no α-H left. A fourth HCHO then reduces it by crossed Cannizzaro (HCHO is oxidised to formate): CH₃CHO + 4HCHO + NaOH → C(CH₂OH)₄ + HCOONa.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-72","question":"Ethyl acetoacetate, CH₃COCH₂COOC₂H₅, is (i) treated with excess LiAlH₄ and, separately, (ii) with NaBH₄ in ethanol. The main products (after work-up) are respectively:","options":["Ethyl 3-hydroxybutanoate in both cases","Butane-1,3-diol in both cases","3-Oxobutanal; butane-1,3-diol","Butane-1,3-diol (+ ethanol); ethyl 3-hydroxybutanoate"],"answer":3,"explanation":"LiAlH₄ reduces both the ketone and the ester (ester → primary alcohol, releasing ethanol), giving CH₃CH(OH)CH₂CH₂OH. NaBH₄ is milder and reduces only the ketone, giving CH₃CH(OH)CH₂COOC₂H₅.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-73","question":"Diethyl malonate is treated with NaOEt and then with bromoethane; the product is hydrolysed with aqueous acid and heated. The final product is:","options":["Butanoic acid","2-Ethylpropanedioic acid","Pentanoic acid","Propanoic acid"],"answer":0,"explanation":"The CH₂ between the two esters is deprotonated and alkylated: EtCH(COOEt)₂. Hydrolysis gives EtCH(COOH)₂, a substituted malonic acid, which loses CO₂ on heating (β-carbonyl acid) to give CH₃CH₂CH₂COOH. Stopping at the diacid ignores the decarboxylation.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-74","question":"Ethyl acetoacetate is treated with NaOEt and then CH₃I; the product is warmed with dilute aqueous acid (ketonic hydrolysis). The final product is:","options":["Propanone","Butan-2-one","Pentan-2-one","2-Methylpropanoic acid"],"answer":1,"explanation":"The active CH₂ is methylated to CH₃COCH(CH₃)COOEt. Hydrolysis gives the β-keto acid CH₃COCH(CH₃)COOH, which decarboxylates to CH₃COCH₂CH₃. Without the alkylation step propanone would form, which is the trap.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-75","question":"Benzaldehyde-d, C₆H₅CDO, is heated with concentrated NaOH in ordinary water. The alcohol formed in the Cannizzaro reaction is:","options":["C₆H₅CH₂OH","C₆H₅CHDOH","C₆H₅CD₂OH","C₆H₅CD₂OD only, because the solvent supplies D"],"answer":2,"explanation":"The hydride that reduces one aldehyde comes from the carbonyl carbon of the other (via the tetrahedral anion C₆H₅CD(OH)O⁻), not from the solvent, so the reduced carbon carries the transferred D plus its own D: C₆H₅CD₂OH. Its O–H hydrogen comes from water. This labelling experiment is the evidence for direct hydride transfer.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id": "chem-carbonyl-acids-76", "question": "Maleic acid (cis-butenedioic acid) and fumaric acid (trans) are compared. Which statement is correct?", "options": ["Fumaric acid has both the lower pKa₁ and the lower pKa₂", "Maleic acid has both the lower pKa₁ and the lower pKa₂", "Maleic acid has the lower pKa₁ but the higher pKa₂", "Both have identical pKa values, since they are isomers"], "answer": 2, "explanation": "The hydrogen-maleate anion is stabilised by an intramolecular hydrogen bond between the COOH and COO⁻ groups held close in the cis isomer, so the first proton is lost easily (pKa₁ ≈ 1.9 vs 3.0). The same hydrogen bond, plus repulsion between two nearby negative charges, makes the second proton harder to remove (pKa₂ ≈ 6.1 vs 4.4).", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-carbonyl-acids-77", "question": "How many of the following statements about benzoic acid are correct? (A) It does not undergo Friedel–Crafts alkylation or acylation. (B) Its nitration gives mainly 3-nitrobenzoic acid. (C) It is a stronger acid than ethanoic acid. (D) Its sodium salt heated with soda lime gives benzene.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. –COOH deactivates the ring and also binds AlCl₃, so Friedel–Crafts fails; it is meta-directing; the sp² ring carbon makes benzoic acid (pKa 4.2) stronger than ethanoic acid (4.76); decarboxylation of sodium benzoate with soda lime gives benzene.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-carbonyl-acids-78", "question": "Assertion (A): Acid-catalysed bromination of propanone can be stopped at the monobromo stage, whereas base-promoted bromination goes on until the haloform reaction occurs. Reason (R): In base, each Br introduced makes the remaining α-H atoms more acidic, so later enolate formation is faster; in acid, Br lowers the basicity of the carbonyl oxygen, so later enolisation is slower.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Base-promoted halogenation speeds up with each substitution (−I effect of Br on α-H acidity), leading to CX₃ and cleavage. Acid-catalysed halogenation needs protonation of C=O first, which Br makes harder, so it slows down after one substitution. R explains A exactly.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-79","question":"1.5 g of methanal (molar mass 30) is warmed with an excess of Tollens' reagent until no more silver forms. The mass of silver deposited is (Ag = 108):","options":["10.8 g","32.4 g","5.4 g","21.6 g"],"answer":3,"explanation":"Methanal is oxidised first to formate (2 Ag per HCHO), and formate, which still has an aldehydic H, is oxidised further to carbonate (2 more Ag), so 1 mol HCHO gives 4 mol Ag. 0.05 mol × 4 × 108 = 21.6 g; assuming 2 Ag per aldehyde gives 10.8 g.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-carbonyl-acids-80", "question": "tert-Butyl acetate labelled with ¹⁸O in the alkoxy oxygen, CH₃CO–¹⁸O–C(CH₃)₃, is hydrolysed in dilute aqueous acid. The label is found in:", "options": ["tert-Butyl alcohol", "Water only", "Both products equally", "Ethanoic acid"], "answer": 3, "explanation": "With a tertiary alkyl group the ester cleaves at the alkyl–oxygen bond (AAL1): the protonated ester loses the stable (CH₃)₃C⁺ cation, leaving CH₃CO–¹⁸OH, and the cation picks up unlabelled water. Ordinary esters (methyl, ethyl) cleave at the acyl–oxygen bond and put the label in the alcohol, which is the trap.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-carbonyl-acids-81", "question": "Cyclohexanone is treated with CH₃MgBr followed by aqueous work-up; the product is heated with conc. H₂SO₄, and the alkene formed is treated with O₃ followed by Zn/H₂O. The final product is:", "options": ["6-Oxoheptanal", "Heptane-2,6-dione", "Hexanedial and methanal", "Cyclohexanone and methanal"], "answer": 0, "explanation": "CH₃MgBr gives 1-methylcyclohexan-1-ol; acid dehydration gives the more substituted (endocyclic) 1-methylcyclohexene, not methylenecyclohexane. Ozonolysis opens the ring: the methyl-bearing carbon becomes a ketone and the CH becomes an aldehyde, giving CH₃CO(CH₂)₄CHO. Assuming the exocyclic alkene gives back cyclohexanone + HCHO, the trap.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-carbonyl-acids-82","question":"A compound C₉H₁₀O forms an orange precipitate with 2,4-DNP, reduces Tollens' reagent and does not give the iodoform test. On vigorous oxidation with hot alkaline KMnO₄ followed by acidification it gives benzene-1,2-dicarboxylic acid (phthalic acid). The compound is:","options":["4-Ethylbenzaldehyde","2-Ethylbenzaldehyde","3-Phenylpropanal","1-Phenylpropan-1-one"],"answer":1,"explanation":"Tollens-positive means an aldehyde; oxidation to phthalic acid means two carbon side chains ortho to each other on the ring (each oxidised to COOH). 2-Ethylbenzaldehyde, C₆H₄(CHO)(C₂H₅), fits. The para isomer would give terephthalic acid, 3-phenylpropanal only benzoic acid, and propiophenone is a ketone (Tollens-negative).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-83","question":"The correct order of reactivity towards nucleophilic addition (e.g. with HCN) is:","options":["p-Methoxybenzaldehyde > p-tolualdehyde > benzaldehyde > p-nitrobenzaldehyde","Benzaldehyde > p-nitrobenzaldehyde > p-tolualdehyde > p-methoxybenzaldehyde","p-Nitrobenzaldehyde > benzaldehyde > p-tolualdehyde > p-methoxybenzaldehyde","p-Nitrobenzaldehyde > p-methoxybenzaldehyde > benzaldehyde > p-tolualdehyde"],"answer":2,"explanation":"Electron-withdrawing –NO₂ (−I, −R) increases the positive charge on the carbonyl carbon; –CH₃ (+I, hyperconjugation) and especially –OCH₃ (+R) feed electron density into it and reduce its electrophilicity.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-84","question":"Which reagent distinguishes propanal from propanone, but does NOT distinguish benzaldehyde from acetophenone?","options":["Tollens' reagent","Iodine and NaOH","2,4-Dinitrophenylhydrazine","Fehling's solution"],"answer":3,"explanation":"Fehling's solution is reduced by aliphatic aldehydes (propanal) but not by ketones, and also not by aromatic aldehydes, so benzaldehyde and acetophenone both give no red Cu₂O. Tollens' and iodoform tests separate both pairs; 2,4-DNP is positive for all four carbonyl compounds.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-carbonyl-acids-85", "question": "How many of the following statements are correct? (A) LiAlH₄ reduces carboxylic acids to primary alcohols. (B) NaBH₄ readily reduces carboxylic acids to primary alcohols. (C) Ethanoic acid in benzene shows an apparent molar mass of about 120 g mol⁻¹. (D) The sodium salt of a carboxylic acid heated with soda lime gives a hydrocarbon with one carbon fewer.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct; in benzene ethanoic acid exists as hydrogen-bonded dimers (2 × 60 = 120). B is wrong: NaBH₄ merely forms the carboxylate salt and does not reduce it, because the carboxylate carbon is too weakly electrophilic.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-carbonyl-acids-86","question":"The IUPAC name of CH₃–CO–CH₂–CH₃ is:","options":["Butan-2-one","Butanal","Propan-2-one","Butan-3-one"],"answer":0,"explanation":"The longest chain containing the C=O group has four carbons, and numbering from the end nearer the carbonyl gives it locant 2, so the name is butan-2-one (ethyl methyl ketone). 'Butan-3-one' violates the lowest-locant rule, and butanal would need a terminal –CHO group.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-87","question":"Table vinegar is a dilute aqueous solution (about 6–8%) of:","options":["Citric acid","Methanoic acid","Propanoic acid","Ethanoic acid"],"answer":3,"explanation":"Vinegar is made by bacterial (Acetobacter) oxidation of ethanol and contains about 6–8% ethanoic (acetic) acid, CH₃COOH. Methanoic acid occurs in ant stings and citric acid in citrus fruits.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-88","question":"Which of the following does NOT give a red precipitate with Fehling's solution?","options":["Propanal","Ethanal","Benzaldehyde","D-Glucose"],"answer":2,"explanation":"Fehling's solution (Cu²⁺–tartrate complex) is a mild oxidant that oxidises aliphatic aldehydes and reducing sugars, depositing red Cu₂O. Aromatic aldehydes such as benzaldehyde are not oxidised by it, although they do reduce the stronger Tollens' reagent. This difference distinguishes aliphatic from aromatic aldehydes.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-89","question":"Benzaldehyde is heated with ethanolic KCN. The product of this benzoin condensation is:","options":["C₆H₅–CH(OH)–CN","C₆H₅–CH(OH)–CO–C₆H₅","C₆H₅–CO–CO–C₆H₅","C₆H₅–CH=CH–COOH"],"answer":1,"explanation":"Cyanide adds to one benzaldehyde, and the cyanohydrin anion (whose benzylic H is now acidic) acts as an acyl-anion equivalent that attacks a second benzaldehyde. Loss of CN⁻ gives benzoin, 2-hydroxy-1,2-diphenylethanone. CN⁻ is a catalyst; mandelonitrile is the HCN addition product and benzil is the oxidised (diketone) form.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-90","question":"Benzaldehyde is heated with acetic anhydride in the presence of sodium acetate. The product isolated after hydrolysis (Perkin reaction) is:","options":["Cinnamic acid, C₆H₅CH=CHCOOH","Benzoic acid","Phenylacetic acid, C₆H₅CH₂COOH","Benzyl acetate"],"answer":0,"explanation":"Acetate ion deprotonates the anhydride at its α-carbon, and the enolate adds to benzaldehyde (an aldol-type step). The adduct is acylated and eliminates acetic acid, giving the α,β-unsaturated acid after hydrolysis. Cinnamic acid (3-phenylprop-2-enoic acid) is formed; benzaldehyde has no α-H, so it can only act as the electrophile.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-91","question":"The active species in Tollens' reagent, prepared by adding just enough NH₃ to dissolve the Ag₂O formed from AgNO₃ and NaOH, is:","options":["[Ag(OH)₂]⁻","[Ag(NH₃)₄]⁺","Ag₂O suspended in water","[Ag(NH₃)₂]⁺"],"answer":3,"explanation":"Ag₂O dissolves in aqueous ammonia as the linear diamminesilver(I) complex [Ag(NH₃)₂]⁺. An aldehyde reduces it to metallic silver (silver mirror) and is itself oxidised to the carboxylate: RCHO + 2[Ag(NH₃)₂]⁺ + 3OH⁻ → RCOO⁻ + 2Ag + 4NH₃ + 2H₂O.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-carbonyl-acids-92","question":"Benzaldehyde oxime is heated with acetic anhydride. The main organic product is:","options":["Benzamide","Benzylamine","Benzonitrile","N-Phenylacetamide"],"answer":2,"explanation":"Acetic anhydride acetylates the oxime –OH, converting it into a good leaving group (–OCOCH₃). For an aldoxime the H on the C=N carbon is then lost along with acetate (an E2-type elimination), giving the nitrile C₆H₅C≡N. Ketoximes, which lack this H, instead undergo Beckmann rearrangement under acidic conditions.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-93","question":"A mixture of propanal and benzaldehyde is treated with dilute NaOH. Ignoring stereoisomers, how many different β-hydroxy carbonyl (aldol) products can form?","options":["One","Two","Three","Four"],"answer":1,"explanation":"Benzaldehyde has no α-hydrogen, so it can only accept an enolate. The propanal enolate can attack another propanal (giving 3-hydroxy-2-methylpentanal) or benzaldehyde (giving 3-hydroxy-2-methyl-3-phenylpropanal). Hence only two aldol products are possible.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-94","question":"The correct decreasing order of acidity of the indicated C–H (α-hydrogen) is:","options":["Pentane-2,4-dione > ethyl acetoacetate > diethyl malonate > propanone","Diethyl malonate > ethyl acetoacetate > pentane-2,4-dione > propanone","Propanone > pentane-2,4-dione > ethyl acetoacetate > diethyl malonate","Ethyl acetoacetate > pentane-2,4-dione > propanone > diethyl malonate"],"answer":0,"explanation":"A CH₂ flanked by two carbonyl groups is far more acidic than one next to a single C=O (propanone, pKa ≈ 19–20). Ester carbonyls stabilise the carbanion less than ketone carbonyls because the alkoxy oxygen donates electrons into C=O. Thus two ketone groups (pKa ≈ 9) > ketone + ester (≈ 11) > two esters (≈ 13).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-95","question":"Methyl benzoate is treated with excess phenylmagnesium bromide, followed by aqueous acid. The product is:","options":["Methyl triphenyl ether","Benzophenone","Diphenylmethanol","Triphenylmethanol"],"answer":3,"explanation":"The first PhMgBr adds to the ester C=O, and the tetrahedral intermediate expels CH₃O⁻ to give benzophenone. A ketone is more reactive than an ester, so it immediately consumes a second equivalent of PhMgBr. Hydrolysis gives the 3° alcohol (C₆H₅)₃COH.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-96","question":"The correct decreasing order of acid strength of the para-substituted benzoic acids is:","options":["p-Chloro > p-nitro > benzoic > p-methoxy","p-Methoxy > benzoic > p-chloro > p-nitro","p-Nitro > p-chloro > benzoic > p-methoxy","p-Nitro > benzoic > p-chloro > p-methoxy"],"answer":2,"explanation":"Electron-withdrawing groups stabilise the benzoate anion: –NO₂ (–I, –R) strongly, –Cl (–I outweighing +R) moderately. –OCH₃ at the para position donates electrons by resonance (+R), destabilising the anion. pKa values: 3.44, 3.98, 4.20 and 4.47 respectively.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-97","question":"Although CH₃ is an electron-releasing group, one of the methylbenzoic (toluic) acids is a STRONGER acid than benzoic acid. It is:","options":["3-Methylbenzoic acid, because of the –I effect of CH₃ at the meta position","2-Methylbenzoic acid, because of the ortho effect","4-Methylbenzoic acid, because of hyperconjugation","None of them; all toluic acids are weaker than benzoic acid"],"answer":1,"explanation":"An ortho substituent pushes the –COOH group out of the plane of the ring (steric inhibition of resonance). This reduces the ring's electron donation into the carboxyl group and favours ionisation, so 2-methylbenzoic acid (pKa ≈ 3.9) is stronger than benzoic acid (4.2). The meta and para isomers (≈ 4.3, 4.4) are weaker, as expected for +I/hyperconjugation.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-98","question":"Most aldehydes exist in water mainly as the carbonyl compound, but trichloroethanal (chloral) forms a stable, isolable hydrate, Cl₃C–CH(OH)₂. The main reason is:","options":["The strong –I effect of the CCl₃ group makes the carbonyl carbon very electrophilic and stabilises the gem-diol, aided by intramolecular hydrogen bonding with Cl","The CCl₃ group donates electrons to the carbonyl carbon","Chloral has no α-carbon and therefore cannot form an enol","Chloral is a ketone, and ketone hydrates are always stable"],"answer":0,"explanation":"Electron withdrawal by three chlorine atoms destabilises the polarised C=O and favours the sp³ addition product. The gem-diol is further stabilised by O–H···Cl hydrogen bonds. The equilibrium therefore lies on the hydrate side, unlike for ethanal; the absence of α-H is irrelevant to hydration.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-99","question":"The rate of reaction of a carbonyl compound with hydroxylamine or 2,4-DNP is highest at about pH 4.5 and falls off in both strongly acidic and neutral/alkaline solution. This is because:","options":["The imine product hydrolyses only at pH 4.5","The carbonyl compound is converted into an enolate below pH 4.5","Hydroxylamine is a stronger nucleophile when protonated","Acid is needed to activate the C=O and to protonate the –OH of the carbinolamine for loss of water, but strong acid converts the nitrogen nucleophile into its unreactive protonated form"],"answer":3,"explanation":"Formation of C=N–Z proceeds by nucleophilic addition to give a carbinolamine, then acid-catalysed dehydration. The dehydration needs H⁺, but the nucleophile H₂N–Z is a base and becomes H₃N⁺–Z, which has no lone pair, when the medium is too acidic. A weakly acidic buffer balances these two requirements.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-100","question":"Methyl 4-oxopentanoate, CH₃COCH₂CH₂COOCH₃, is to be converted into 5-hydroxypentan-2-one, CH₃COCH₂CH₂CH₂OH. The correct sequence is:","options":["(i) NaBH₄ in ethanol; (ii) dilute H₃O⁺","(i) LiAlH₄, then H₂O; (ii) PCC","(i) Ethane-1,2-diol, dry HCl; (ii) LiAlH₄, then H₂O; (iii) dilute aqueous H₃O⁺","(i) H₂, Pd–BaSO₄; (ii) dilute H₃O⁺"],"answer":2,"explanation":"LiAlH₄ would reduce both the ketone and the ester, so the ketone is first protected as a cyclic ketal, which is stable to strong bases and hydride reagents. LiAlH₄ then reduces the ester to –CH₂OH, and aqueous acid removes the ketal to restore the C=O. NaBH₄ would do the opposite — reduce only the ketone.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-101","question":"Alkaline hydrolysis (saponification) of an ester goes to completion, whereas acid-catalysed hydrolysis is reversible. The reason is:","options":["OH⁻ is a weaker nucleophile than water","The carboxylic acid formed is immediately deprotonated to a resonance-stabilised carboxylate ion, which the alcohol cannot attack","In alkaline medium the alcohol is protonated and removed","Alkaline hydrolysis proceeds by alkyl–oxygen cleavage"],"answer":1,"explanation":"In base, the tetrahedral intermediate expels RO⁻, and the carboxylic acid formed transfers a proton to RO⁻ or OH⁻, giving RCOO⁻. The carboxylate's delocalised negative charge makes it unreactive towards nucleophiles, so the reverse (esterification) cannot occur. In acid every step, including attack of ROH on RCOOH, is reversible.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-102","question":"Acetophenone is treated with a peroxyacid such as m-CPBA (Baeyer–Villiger oxidation). The product is:","options":["Phenyl ethanoate, CH₃COOC₆H₅","Methyl benzoate, C₆H₅COOCH₃","Benzoic acid and methanol","2-Hydroxyacetophenone"],"answer":0,"explanation":"The peroxyacid adds to C=O, and one group migrates from carbon to the electron-deficient oxygen as the carboxylate leaves. Migratory aptitude is roughly 3° alkyl > cyclohexyl ≈ 2° alkyl ≈ phenyl > 1° alkyl > methyl, so phenyl migrates rather than CH₃. An O is thus inserted between the carbonyl carbon and phenyl, giving phenyl acetate.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-carbonyl-acids-103","question":"Cyclohexene is treated with O₃ followed by Zn/H₂O, and the product is warmed with dilute NaOH. The final product is:","options":["Cyclopentanone","Cyclohex-2-en-1-one","Hexanedioic acid","Cyclopent-1-ene-1-carbaldehyde"],"answer":3,"explanation":"Reductive ozonolysis opens the ring to hexanedial, OHC(CH₂)₄CHO. An enolate formed at C-2 attacks the C-6 carbonyl, forming a five-membered ring (favoured over three- or seven-membered alternatives). Dehydration of the β-hydroxy aldehyde gives the conjugated cyclopent-1-ene-1-carbaldehyde.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-104","question":"Ethyl 4-oxopentanoate, CH₃COCH₂CH₂COOC₂H₅, is reduced with NaBH₄ in ethanol and the product is warmed with a trace of acid. The final product is:","options":["Ethyl 4-hydroxypentanoate, which does not change","Pentane-1,4-diol","γ-Valerolactone (5-methyloxolan-2-one)","4-Oxopentanal"],"answer":2,"explanation":"NaBH₄ reduces the ketone to a secondary alcohol but leaves the ester untouched, giving ethyl 4-hydroxypentanoate. The –OH is positioned γ to the ester carbonyl, so acid catalyses an intramolecular transesterification forming a strain-free five-membered lactone and releasing ethanol. LiAlH₄ would instead give pentane-1,4-diol.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-105","question":"1.18 g of a saturated dicarboxylic acid is exactly neutralised by 20.0 mL of 1.0 M NaOH. The acid is:","options":["Propanedioic (malonic) acid","Butanedioic (succinic) acid","Hexanedioic (adipic) acid","Ethanedioic (oxalic) acid"],"answer":1,"explanation":"NaOH used = 0.020 mol; a dibasic acid needs 2 mol NaOH per mole, so the acid is 0.010 mol. Molar mass = 1.18/0.010 = 118 g mol⁻¹, which matches HOOC–CH₂CH₂–COOH (C₄H₆O₄). Oxalic, malonic and adipic acids have molar masses 90, 104 and 146.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-106","question":"Propanal undergoes self-aldol addition with dilute NaOH, and the aldol is then dehydrated by heating. The numbers of stereoisomers possible for the aldol and for the dehydrated product are respectively:","options":["2 and 2","4 and 1","2 and 1","4 and 2"],"answer":3,"explanation":"The aldol is CH₃CH₂–CH(OH)–CH(CH₃)–CHO, 3-hydroxy-2-methylpentanal; C-2 and C-3 are both stereocentres, giving 2² = 4 stereoisomers. Dehydration gives CH₃CH₂CH=C(CH₃)CHO (2-methylpent-2-enal), which has no stereocentre but has two different groups on each alkene carbon, so E and Z forms exist.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-107","question":"8.6 g of pentan-2-one (M = 86 g mol⁻¹) reacts completely with I₂ and NaOH. The mass of iodoform formed (CHI₃ = 394 g mol⁻¹) and the moles of I₂ consumed are:","options":["39.4 g; 0.3 mol","39.4 g; 0.1 mol","13.1 g; 0.3 mol","19.7 g; 0.15 mol"],"answer":0,"explanation":"RCOCH₃ + 3I₂ + 4NaOH → RCOONa + CHI₃ + 3NaI + 3H₂O. The ketone is 8.6/86 = 0.1 mol, giving 0.1 mol CHI₃ = 39.4 g, and 3 × 0.1 = 0.3 mol I₂ is used to triiodinate the methyl group. The other product is sodium butanoate.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-108","question":"The correct decreasing order of acid strength is:","options":["FCH₂COOH > ClCH₂COOH > Cl₂CHCOOH > CH₃COOH","FCH₂COOH > Cl₂CHCOOH > ClCH₂COOH > CH₃COOH","Cl₂CHCOOH > FCH₂COOH > ClCH₂COOH > CH₃COOH","Cl₂CHCOOH > ClCH₂COOH > FCH₂COOH > CH₃COOH"],"answer":2,"explanation":"F has a stronger –I effect than Cl, so FCH₂COOH (pKa ≈ 2.6) is stronger than ClCH₂COOH (≈ 2.9). But two chlorine atoms on the α-carbon withdraw much more electron density than a single fluorine, making Cl₂CHCOOH (≈ 1.3) the strongest. Ethanoic acid (4.76) is weakest.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-109","question":"Propanoic acid is treated in turn with (i) SOCl₂, (ii) NH₃, (iii) P₂O₅, heat and (iv) CH₃MgBr followed by H₃O⁺. The final product is:","options":["Propanone","Butan-2-one","Butan-2-ol","Butanal"],"answer":1,"explanation":"SOCl₂ gives propanoyl chloride, ammonia converts it to propanamide, and P₂O₅ dehydrates the amide to propanenitrile, CH₃CH₂C≡N. CH₃MgBr adds once to the nitrile to give an imine salt that is hydrolysed to the ketone CH₃CH₂COCH₃. The nitrile route stops at the ketone because the imine anion does not react further.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-110","question":"Benzene is treated in turn with (i) succinic anhydride/anhydrous AlCl₃, (ii) Zn–Hg/conc. HCl and (iii) conc. H₂SO₄ (or H₃PO₄), heat. The final product is:","options":["1-Tetralone (3,4-dihydronaphthalen-1(2H)-one)","4-Phenylbutanoic acid","4-Oxo-4-phenylbutanoic acid","Naphthalene"],"answer":0,"explanation":"Friedel–Crafts acylation with succinic anhydride gives C₆H₅CO(CH₂)₂COOH. Clemmensen reduction removes the ketone, giving C₆H₅(CH₂)₃COOH, and hot acid then brings about intramolecular Friedel–Crafts acylation onto the ortho position, closing a six-membered ring. This is the first stage of the Haworth synthesis of naphthalene.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-111","question":"How many of the following statements are correct? (A) Methanal reacts with ammonia to give hexamethylenetetramine (urotropine). (B) Benzaldehyde reacts with ammonia to give hydrobenzamide. (C) Ketones readily restore the pink colour of Schiff's reagent. (D) Methanal undergoes aldol condensation with dilute NaOH. (E) Ethanal forms a cyclic trimer, paraldehyde, with a trace of conc. H₂SO₄.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(A) 6HCHO + 4NH₃ → (CH₂)₆N₄ + 6H₂O is true; (B) 3C₆H₅CHO + 2NH₃ → (C₆H₅CH=N)₂CHC₆H₅ is true; (E) is true. (C) is false — Schiff's test is characteristic of aldehydes. (D) is false because methanal has no α-hydrogen; with concentrated alkali it undergoes Cannizzaro reaction instead. Three are correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-112","question":"The oxime of acetophenone in which the –OH group is anti to the phenyl group is warmed with conc. H₂SO₄ (Beckmann rearrangement). The product is:","options":["Acetophenone and hydroxylamine","N-Methylbenzamide, C₆H₅CONHCH₃","Benzonitrile and methanol","Acetanilide, CH₃CONHC₆H₅"],"answer":3,"explanation":"Protonation turns –OH into a good leaving group, and the group anti to it migrates from carbon to nitrogen as water leaves. Here phenyl migrates, giving the nitrilium ion CH₃C≡N⁺–C₆H₅, which adds water and tautomerises to the amide CH₃CONHC₆H₅. Methyl migration (from the other geometrical isomer) would give N-methylbenzamide.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-113","question":"Propanoic acid is treated with Br₂ and red phosphorus, and the product is heated with excess concentrated aqueous NH₃. The final product is:","options":["(S)-2-Aminopropanoic acid only","(±)-2-Aminopropanoic acid (racemic alanine)","3-Aminopropanoic acid (β-alanine)","Propanamide"],"answer":1,"explanation":"The Hell–Volhard–Zelinsky reaction brominates the α-carbon via the acyl bromide enol, giving 2-bromopropanoic acid. Excess ammonia displaces bromide by SN2 at C-2, giving the α-amino acid. Since the bromo acid is racemic, the alanine formed is racemic, not the natural L-form.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-114","question":"Benzil, C₆H₅CO–COC₆H₅, is heated with concentrated aqueous KOH and the solution is then acidified. The product is:","options":["2-Hydroxy-2,2-diphenylethanoic (benzilic) acid","Benzoic acid only","Benzoin","Diphenylmethanol and CO₂"],"answer":0,"explanation":"OH⁻ adds to one carbonyl group; the tetrahedral alkoxide then pushes a phenyl group (with its bonding pair) onto the adjacent carbonyl carbon — a 1,2-shift analogous to the hydride shift in Cannizzaro. Proton transfer gives the carboxylate (C₆H₅)₂C(OH)COO⁻, and acidification yields benzilic acid.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-115","question":"Benzene-1,2-dicarbaldehyde (phthalaldehyde) is heated with concentrated NaOH, and the solution is then acidified and warmed. The final product is:","options":["Phthalic anhydride","Phthalic acid","Benzene-1,2-dimethanol","Phthalide, a five-membered lactone (isobenzofuran-1(3H)-one)"],"answer":3,"explanation":"With no α-hydrogens, the two –CHO groups undergo an intramolecular Cannizzaro reaction: one is oxidised to –COO⁻ and the other reduced to –CH₂OH, giving 2-(hydroxymethyl)benzoate. On acidification the ortho –COOH and –CH₂OH groups cyclise to the five-membered lactone phthalide. Only one hydride transfer occurs per molecule.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-116","question":"Butan-2-one is brominated with one equivalent of Br₂ (a) in acetic acid with a trace of HBr, and (b) with excess Br₂ in aqueous NaOH. The main organic products are:","options":["(a) 1-bromobutan-2-one; (b) bromoform and propanoate ion","(a) 1-bromobutan-2-one; (b) 3,3-dibromobutan-2-one","(a) 3-bromobutan-2-one; (b) bromoform and propanoate ion","(a) 3-bromobutan-2-one; (b) 1,3-dibromobutan-2-one"],"answer":2,"explanation":"Acid catalysis goes through the enol, and the more substituted enol (C=C towards C-3) forms preferentially, so bromination occurs at the CH₂. In base, enolate formation at the methyl group is faster; each Br introduced makes the remaining H on that carbon more acidic, so the CH₃ becomes CBr₃. The tribromoketone is then cleaved by OH⁻ (haloform reaction) to CHBr₃ and CH₃CH₂COO⁻.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-117","question":"Ethyl methanoate (HCOOC₂H₅) is treated with excess CH₃MgBr, followed by aqueous NH₄Cl. The main product is:","options":["2-Methylpropan-2-ol","Propan-2-ol","Ethanol only","Ethanal"],"answer":1,"explanation":"The first equivalent of CH₃MgBr adds to the ester, and loss of C₂H₅O⁻ gives ethanal. The aldehyde is more reactive than the ester and immediately adds a second CH₃MgBr, giving (CH₃)₂CHO⁻MgBr⁺, which work-up converts to propan-2-ol. A formate ester therefore gives a secondary alcohol, while other esters give tertiary alcohols; ethanol is formed only as a by-product.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-carbonyl-acids-118","question":"Aldehydes can be separated from a mixture with non-carbonyl compounds by shaking with saturated NaHSO₃ solution because:","options":["They form crystalline bisulphite addition compounds that can be filtered off and decomposed back to the aldehyde with dilute acid or alkali","NaHSO₃ oxidises aldehydes to acids, which are water-soluble","NaHSO₃ reduces aldehydes to alcohols, which separate as a layer","Aldehydes are insoluble in water but bisulphite makes the other compounds insoluble"],"answer":0,"explanation":"HSO₃⁻ adds through sulphur to the carbonyl carbon, forming RCH(OH)SO₃⁻Na⁺, an ionic solid that crystallises from the saturated solution. The addition is reversible: dilute HCl or Na₂CO₃ destroys free bisulphite and regenerates the carbonyl compound. Most methyl ketones react similarly, but bulkier ketones do not.","difficulty":"moderate","source":"JEE Main · NEET"},
];

export default questions;
